css:
html { color-scheme: light; }
:root[data-theme-id="sky-cloud"] [data-region="root"] {
  background: var(--bg-gradient) !important;
}
:root[data-theme-id="sky-cloud"] [data-region="bg-decoration"] {
  overflow: hidden;
  background: var(--bg-gradient) !important;
}
:root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::before,
:root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::after {
  content: "";
  position: absolute;
  left: 0;
  width: 100%;
  pointer-events: none;
  background-repeat: no-repeat;
}
:root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::before {
  top: 10%;
  height: 120px;
  opacity: 0.4;
  background-image: radial-gradient(ellipse at 20% 50%, rgba(255,255,255,0.8) 0%, transparent 50%),
    radial-gradient(ellipse at 60% 30%, rgba(255,255,255,0.6) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 60%, rgba(255,255,255,0.7) 0%, transparent 50%);
  background-size: 300px 80px, 400px 100px, 350px 90px;
  animation: sky-cloud-drift 120s linear infinite;
}
:root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::after {
  top: 60%;
  height: 100px;
  opacity: 0.3;
  background-image: radial-gradient(ellipse at 30% 50%, rgba(255,255,255,0.6) 0%, transparent 50%),
    radial-gradient(ellipse at 70% 40%, rgba(255,255,255,0.5) 0%, transparent 50%);
  background-size: 350px 90px, 300px 80px;
  animation: sky-cloud-drift 100s linear infinite reverse;
}
:root[data-theme-id="sky-cloud"] [data-region="main"] {
  isolation: isolate;
  background: transparent !important;
}
:root[data-theme-id="sky-cloud"] [data-region="sidebar"] {
  background: var(--bg-surface) !important;
  border-right: 1px solid var(--border-subtle);
}
:root[data-theme-id="sky-cloud"] [data-region="searchbar"] {
  background: var(--bg-surface) !important;
  border-bottom: 1px solid var(--border-subtle);
}
:root[data-theme-id="sky-cloud"] [data-region="titlebar"] {
  background: var(--bg-surface) !important;
  border-bottom: 1px solid var(--border-subtle);
}
:root[data-theme-id="sky-cloud"] .surface-card,
:root[data-theme-id="sky-cloud"] .surface-card-soft,
:root[data-theme-id="sky-cloud"] .modal-surface,
:root[data-theme-id="sky-cloud"] .mod-panel-floating {
  border-color: var(--border-default) !important;
  background: var(--bg-card) !important;
  box-shadow: var(--shadow-sm);
}
:root[data-theme-id="sky-cloud"] .item-card-render-scope {
  border-color: var(--border-default) !important;
  background: var(--bg-card) !important;
  box-shadow: var(--shadow-card);
}
:root[data-theme-id="sky-cloud"] .item-card-render-scope::before {
  display: none !important;
}
:root[data-theme-id="sky-cloud"] .item-row-render-scope {
  background: var(--bg-surface) !important;
}
:root[data-theme-id="sky-cloud"] .action-button,
:root[data-theme-id="sky-cloud"] .control-chip {
  border-color: var(--border-default);
  background: var(--bg-input);
}
:root[data-theme-id="sky-cloud"] .action-button-primary,
:root[data-theme-id="sky-cloud"] .control-chip-active {
  background: var(--accent-primary) !important;
  color: var(--text-invert);
  border-color: var(--accent-primary);
}
:root[data-theme-id="sky-cloud"] .empty-state-panel {
  background: var(--bg-surface) !important;
}
:root[data-theme-id="sky-cloud"] .text-label {
  color: #5e3d87;
}
@keyframes sky-cloud-drift {
  from { transform: translateX(-100px); }
  to { transform: translateX(100px); }
}
@media (prefers-reduced-motion: reduce) {
  :root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::before,
  :root[data-theme-id="sky-cloud"] [data-region="bg-decoration"]::after {
    animation: none !important;
  }
}
